const input = $json.body ?? $json;

const message =
  input.message ??
  input.text ??
  input.transcript ??
  "";

const inputType =
  input.input_type ??
  input.type ??
  "text";

const sessionId =
  input.session_id ??
  `session_${Date.now()}`;

return [
  {
    json: {
      session_id: sessionId,
      input_type: inputType,
      user_message: String(message).trim(),
      received_at: new Date().toISOString()
    }
  }
];

const output = $json.text || "";

let cleaned = output.trim();

cleaned = cleaned.replace(/^```json\s*/i, "");
cleaned = cleaned.replace(/^```\s*/i, "");
cleaned = cleaned.replace(/\s*```$/i, "");

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    "Gemini returned invalid JSON. Raw output: " + output
  );
}

return [
  {
    json: {
      ...$json,
      extracted_financial_data: parsed
    }
  }
];

const data = $json.extracted_financial_data || {};

return [
  {
    json: {
      session_id: $json.session_id,
      input_type: $json.input_type,
      user_message: $json.user_message,

      business_information: data.business_information || {},

      financial_information: data.financial_information || {},

      credit_information: data.credit_information || {},

      missing_information: data.missing_information || [],

      extraction_confidence: data.confidence || "LOW"
    }
  }
];
